import json
for f in ['e7e6e494-da0b-429f-8083-96c95f66a46f.jsonl','8f7bba12-e8cf-443e-a6de-815446c4d65f.jsonl']:
    rows=[]
    for l in open(f):
        try: rows.append(json.loads(l))
        except: pass
    started=False
    for r in rows:
        ts=r.get('timestamp','')
        if ts < '2026-09-21T23:20': continue
        m=r.get('message') or {}
        c=m.get('content')
        if r.get('type')=='user':
            txt = c if isinstance(c,str) else ' '.join(b.get('text','') for b in (c or []) if isinstance(b,dict) and b.get('type')=='text')
            if txt and not txt.startswith('<') and len(txt)>3:
                print(f'\n>>> VOCÊ {ts[:16]}:', txt[:1500])
        elif r.get('type')=='assistant' and isinstance(c,list):
            for b in c:
                if b.get('type')=='text' and len(b['text'])>400:
                    print(f'--- AGENTE {ts[:16]}:', b['text'][:900].replace('\n',' '))
    print('=========== fim de', f)
EOF
